FIELDS = ["course_id", "title", "provider", "level", "duration_weeks", "rating", "enrolled_k", "skills", "url"]

def main():
    with open("courses.csv", "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=FIELDS)
        writer.writeheader()
        for i, c in enumerate(COURSES, start=1):
            writer.writerow({
                "course_id": f"C{i:03d}",
                "title": c[0], "provider": c[1], "level": c[2], "duration_weeks": c[3],
                "rating": c[4], "enrolled_k": c[5], "skills": ";".join(c[6]), "url": c[7],
            })
    print(f"Wrote {len(COURSES)} courses to courses.csv")

if __name__ == "__main__":
    main()
